for shell in bash zsh fish powershell elvish; do cp "/tmp/dua_completion_$shell.txt" "src/completions/$shell.txt"; done
cat > src/dua.py <<'PY'
#!/usr/bin/env python3
import os
import sys
import stat as statmod
from dataclasses import dataclass

GREEN = b"\033[32m"
CYAN = b"\033[36m"
RESET = b"\033[39m"
FORMATS = ["metric", "binary", "bytes", "gb", "gib", "mb", "mib"]
DEFAULT_IGNORES = ["/proc", "/dev", "/sys", "/run"]

