COMP_HELP = """Generate shell completions

Usage: executable completions <SHELL>

Arguments:
  <SHELL>  The shell to generate a completions-script for [possible values: bash, elvish, fish, powershell, zsh]

Options:
  -h, --help  Print help
"""

@dataclass
class Config:
    fmt: str = "binary"
    apparent: bool = False
    count_hard_links: bool = False
    stay_on_filesystem: bool = False
    ignore_dirs: list = None
    log_file: str = None

@dataclass
class Item:
    path: str
    display: str
    size: int
    is_cyan: bool = False
    errors: int = 0
    pure_error: bool = False

class Stats:
    def __init__(self):
        self.entries = 0
        self.smallest = None
        self.largest = None
    def add(self, n):
        self.entries += 1
        if self.smallest is None or n < self.smallest:
            self.smallest = n
        if self.largest is None or n > self.largest:
            self.largest = n
    def line(self):
        sm = 0 if self.smallest is None else self.smallest
        lg = 0 if self.largest is None else self.largest
        return f"Statistics {{ entries_traversed: {self.entries}, smallest_file_in_bytes: {sm}, largest_file_in_bytes: {lg} }}\n"

class Walker:
    def __init__(self, cfg, stats):
        self.cfg = cfg
        self.stats = stats
        self.seen = set()
        self.root_devs = []
    def own_size(self, st):
        if self.cfg.apparent:
            return int(st.st_size)
        return int(getattr(st, 'st_blocks', 0)) * 512
    def counted_own_size(self, path, lst, target_st, is_symlink):
        n = self.own_size(lst)
        # dua de-duplicates hard-linked regular files unless requested. Symlinks
        # are counted as links themselves, not as their target inode.
        if (not self.cfg.count_hard_links and not is_symlink and
            statmod.S_ISREG(lst.st_mode) and getattr(lst, 'st_nlink', 1) > 1):
            key = (lst.st_dev, lst.st_ino)
            if key in self.seen:
                n = 0
            else:
                self.seen.add(key)
        return n
    def stat_pair(self, path):
        try:
            lst = os.lstat(path)
            st = os.stat(path)
            return lst, st, None
        except OSError as e:
            return None, None, e
    def is_ignored_dir(self, path, is_root):
        if is_root:
            return False
        try:
            ap = os.path.abspath(path)
        except Exception:
            ap = path
        return ap in set(self.cfg.ignore_dirs or [])
    def compute(self, path, include_self=True, is_root=False, root_dev=None):
        lst, st, err = self.stat_pair(path)
        if err is not None:
            return Item(path, path, 0, True, 1, True)
        is_symlink = statmod.S_ISLNK(lst.st_mode)
        target_is_dir = statmod.S_ISDIR(st.st_mode)
        target_is_reg = statmod.S_ISREG(st.st_mode)
        cyan = target_is_dir or (not target_is_reg and not is_symlink)
        total = 0
        if include_self:
            own = self.counted_own_size(path, lst, st, is_symlink)
            total += own
            self.stats.add(own)
        # Traverse directories (including a root symlink to a directory). Symlink
        # descendants are pruned by the caller before compute() is invoked.
        if target_is_dir:
            if root_dev is None:
                root_dev = st.st_dev
            if (self.cfg.stay_on_filesystem and not is_root and st.st_dev != root_dev):
                return Item(path, path, total, cyan, 0, False)
            if self.is_ignored_dir(path, is_root):
                return Item(path, path, total, cyan, 0, False)
            try:
                entries = sorted(list(os.scandir(path)), key=lambda e: os.fsencode(e.name))
            except OSError:
                # Permission denied during traversal is treated as an empty dir.
                entries = []
            for ent in entries:
                try:
                    if ent.is_symlink():
                        continue
                except OSError:
                    continue
                child = self.compute(ent.path, include_self=True, is_root=False, root_dev=root_dev)
                total += child.size
                # stat failures below roots are rare; count them if seen.
                if child.errors:
                    pass
        return Item(path, path, total, cyan, 0, False)

def fsbytes(s):
    return os.fsencode(s)

def fmt_size(n, fmt):
    n = int(n)
    if fmt == 'bytes':
        return f"{n:10d} b"
    if fmt == 'gb':
        return f"{n/1_000_000_000:7.2f} GB"
    if fmt == 'gib':
        return f"{n/(1024**3):6.2f} GiB"
    if fmt == 'mb':
        return f"{n/1_000_000:9.2f} MB"
    if fmt == 'mib':
        return f"{n/(1024**2):8.2f} MiB"
    if fmt == 'metric':
        units = [('GB', 1_000_000_000), ('MB', 1_000_000), ('KB', 1_000)]
        for unit, base in units:
            if n > base:
                return f"{n/base:7.2f} {unit}"
        return f"{n:7d}  B"
    # binary
    units = [('GiB', 1024**3), ('MiB', 1024**2), ('KiB', 1024)]
    for unit, base in units:
        if n > base:
            return f"{n/base:7.2f} {unit}"
    return f"{n:7d}   B"

def write_item(item, cfg, suffix_errors=False):
    out = bytearray()
    out += GREEN + fmt_size(item.size, cfg.fmt).encode('ascii') + RESET + b' '
    if item.is_cyan:
        out += CYAN + fsbytes(item.display) + RESET
    else:
        out += fsbytes(item.display)
    if suffix_errors and item.errors:
        if item.errors == 1:
            out += b"  <1 IO Error>"
        else:
            out += f"  <{item.errors} IO Errors>".encode('ascii')
    out += b"\n"
    sys.stdout.buffer.write(out)

def write_total(total, errors, cfg):
    item = Item('', 'total', total, False, errors, False)
    write_item(item, cfg, suffix_errors=errors > 0)

def child_items_for_dir(path, walker):
    try:
        entries = sorted(list(os.scandir(path)), key=lambda e: os.fsencode(e.name))
    except OSError:
        entries = []
    items = []
    try:
        st_root = os.stat(path)
        root_dev = st_root.st_dev
    except OSError:
        root_dev = None
    for ent in entries:
        try:
            if ent.is_symlink():
                continue
        except OSError:
            continue
        it = walker.compute(ent.path, include_self=True, is_root=False, root_dev=root_dev)
        it.display = ent.name
        items.append(it)
    return items

def cwd_items(walker):
    try:
        entries = sorted(list(os.scandir('.')), key=lambda e: os.fsencode(e.name))
    except OSError:
        entries = []
    try:
        root_dev = os.stat('.').st_dev
    except OSError:
        root_dev = None
    items = []
    for ent in entries:
        try:
            if ent.is_symlink():
                continue
        except OSError:
            continue
        it = walker.compute(ent.path, include_self=True, is_root=False, root_dev=root_dev)
        it.display = ent.name
        items.append(it)
    return items

def should_list_directory(inputs):
    if len(inputs) != 1:
        return False
    try:
        return statmod.S_ISDIR(os.stat(inputs[0]).st_mode)
    except OSError:
        return False

def run_aggregate(cfg, inputs, no_sort=False, no_total=False, stats_flag=False):
    if cfg.ignore_dirs is None:
        cfg.ignore_dirs = list(DEFAULT_IGNORES)
    if cfg.log_file:
        try:
            with open(cfg.log_file, 'w', encoding='utf-8') as f:
                f.write('dua debug log\n')
        except OSError:
            pass
    stats = Stats()
    walker = Walker(cfg, stats)
    total_errors = 0
    show_total = False
    items = []
    single_dir_listing = False
    if not inputs:
        items = cwd_items(walker)
        show_total = len(items) > 1 and not no_total
    elif should_list_directory(inputs):
        single_dir_listing = True
        items = child_items_for_dir(inputs[0], walker)
        show_total = len(items) > 1 and not no_total
    else:
        show_total = len(inputs) > 1 and not no_total
        for p in inputs:
            try:
                root_dev = os.stat(p).st_dev
            except OSError:
                root_dev = None
            it = walker.compute(p, include_self=True, is_root=True, root_dev=root_dev)
            it.display = p
            items.append(it)
            total_errors += it.errors
    if inputs and single_dir_listing:
        total_errors = sum(it.errors for it in items)
    elif not inputs:
        total_errors = sum(it.errors for it in items)
    # Sorting by aggregate byte count, preserving the traversal/argument order for ties.
    printable = items[:]
    if no_sort:
        # The original streaming no-sort mode suppresses individual stat errors,
        # while still reporting their count in the total line/exit code.
        printable = [it for it in printable if not it.pure_error]
    else:
        printable = sorted(printable, key=lambda it: it.size)
    total_size = sum(it.size for it in items if not it.pure_error)
    if not inputs or single_dir_listing:
        total_size = sum(it.size for it in items)
    for it in printable:
        write_item(it, cfg, suffix_errors=(it.errors > 0 and not no_sort))
    if show_total:
        write_total(total_size, total_errors, cfg)
    if stats_flag:
        sys.stderr.write(stats.line())
    return 1 if total_errors else 0

def eprint_error(msg, usage=None, tip=None, extra=None):
    sys.stderr.write(f"error: {msg}\n")
    if extra:
        sys.stderr.write(extra)
    if tip:
        sys.stderr.write(f"\n  tip: {tip}\n")
    if usage:
        sys.stderr.write(f"\nUsage: {usage}\n")
    sys.stderr.write("\nFor more information, try '--help'.\n")
    return 2

def need_value(opt, value_name, possible=False):
    extra = None
    if possible:
        extra = "  [possible values: metric, binary, bytes, gb, gib, mb, mib]\n"
    return eprint_error(f"a value is required for '{opt} <{value_name}>' but none was supplied", extra=extra)

def invalid_unexpected(arg, usage):
    return eprint_error(f"unexpected argument '{arg}' found", usage=usage, tip=f"to pass '{arg}' as a value, use '-- {arg}'")

def parse_u64(s, opt):
    try:
        if s.startswith('-'):
            raise ValueError('invalid digit found in string')
        int(s)
        return True, None
    except Exception:
        return False, eprint_error(f"invalid value '{s}' for '{opt} <THREADS>': invalid digit found in string")

def set_format(cfg, val):
    if val not in FORMATS:
        return eprint_error(f"invalid value '{val}' for '--format <FORMAT>'", extra="  [possible values: metric, binary, bytes, gb, gib, mb, mib]\n")
    cfg.fmt = val
    return None

def parse_global(args):
    cfg = Config(ignore_dirs=list(DEFAULT_IGNORES))
    inputs = []
    i = 0
    end_opts = False
    seen_pos = False
    while i < len(args):
        a = args[i]
        if end_opts:
            inputs.append(a); seen_pos = True; i += 1; continue
        if a == '--':
            end_opts = True; i += 1; continue
        if not seen_pos and a in ('interactive', 'i', 'aggregate', 'a', 'completions', 'help'):
            return cfg, inputs, a, args[i+1:], 0
        if a == '--help':
            sys.stdout.write(LONG_HELP); return cfg, inputs, None, [], 'exit0'
        if a == '-h':
            sys.stdout.write(SHORT_HELP); return cfg, inputs, None, [], 'exit0'
        if a in ('--version', '-V'):
            sys.stdout.write('dua 2.32.2\n'); return cfg, inputs, None, [], 'exit0'
        if a.startswith('--format='):
            err = set_format(cfg, a.split('=',1)[1]);
            if err is not None: return cfg, inputs, None, [], err
            i += 1; continue
        if a == '--format':
            if i+1 >= len(args): return cfg, inputs, None, [], need_value('--format','FORMAT', True)
            err = set_format(cfg, args[i+1]);
            if err is not None: return cfg, inputs, None, [], err
            i += 2; continue
        if a.startswith('--threads='):
            ok, err = parse_u64(a.split('=',1)[1], '--threads')
            if not ok: return cfg, inputs, None, [], err
            i += 1; continue
        if a == '--threads':
            if i+1 >= len(args): return cfg, inputs, None, [], need_value('--threads','THREADS')
            ok, err = parse_u64(args[i+1], '--threads')
            if not ok: return cfg, inputs, None, [], err
            i += 2; continue
        if a.startswith('--ignore-dirs='):
            cfg.ignore_dirs.append(a.split('=',1)[1]); i += 1; continue
        if a == '--ignore-dirs':
            if i+1 >= len(args): return cfg, inputs, None, [], need_value('--ignore-dirs','IGNORE_DIRS')
            cfg.ignore_dirs.append(args[i+1]); i += 2; continue
        if a.startswith('--log-file='):
            cfg.log_file = a.split('=',1)[1]; i += 1; continue
        if a == '--log-file':
            if i+1 >= len(args): return cfg, inputs, None, [], need_value('--log-file','LOG_FILE')
            cfg.log_file = args[i+1]; i += 2; continue
        if a == '--apparent-size': cfg.apparent = True; i += 1; continue
        if a == '--count-hard-links': cfg.count_hard_links = True; i += 1; continue
        if a == '--stay-on-filesystem': cfg.stay_on_filesystem = True; i += 1; continue
        if a.startswith('--'):
            return cfg, inputs, None, [], invalid_unexpected(a, 'dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]...')
        if a.startswith('-') and a != '-':
            j = 1
            while j < len(a):
                ch = a[j]
                if ch == 'A': cfg.apparent = True; j += 1; continue
                if ch == 'l': cfg.count_hard_links = True; j += 1; continue
                if ch == 'x': cfg.stay_on_filesystem = True; j += 1; continue
                if ch == 'V': sys.stdout.write('dua 2.32.2\n'); return cfg, inputs, None, [], 'exit0'
                if ch == 'h': sys.stdout.write(SHORT_HELP); return cfg, inputs, None, [], 'exit0'
                if ch in ('f','t','i'):
                    rest = a[j+1:]
                    if rest:
                        val = rest
                        consume_next = False
                    else:
                        if i+1 >= len(args):
                            if ch == 'f': return cfg, inputs, None, [], need_value('--format','FORMAT', True)
                            if ch == 't': return cfg, inputs, None, [], need_value('--threads','THREADS')
                            return cfg, inputs, None, [], need_value('--ignore-dirs','IGNORE_DIRS')
                        val = args[i+1]; consume_next = True
                    if ch == 'f':
                        err = set_format(cfg, val)
                        if err is not None: return cfg, inputs, None, [], err
                    elif ch == 't':
                        ok, err = parse_u64(val, '--threads')
                        if not ok: return cfg, inputs, None, [], err
                    else:
                        cfg.ignore_dirs.append(val)
                    if consume_next: i += 1
                    j = len(a); break
                return cfg, inputs, None, [], invalid_unexpected('-'+ch, 'dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]...')
            i += 1; continue
        inputs.append(a); seen_pos = True; i += 1
    return cfg, inputs, None, [], 0

def parse_aggregate_args(args):
    no_sort = False; no_total = False; stats = False; inputs = []
    end = False; i = 0
    while i < len(args):
        a = args[i]
        if end:
            inputs.append(a); i += 1; continue
        if a == '--': end = True; i += 1; continue
        if a in ('-h', '--help'):
            sys.stdout.write(AGG_HELP); return None
        if a == '--stats': stats = True; i += 1; continue
        if a == '--no-sort': no_sort = True; i += 1; continue
        if a == '--no-total': no_total = True; i += 1; continue
        if a.startswith('-') and a != '-':
            return invalid_unexpected(a, 'executable aggregate [OPTIONS] [INPUT]...')
        inputs.append(a); i += 1
    return inputs, no_sort, no_total, stats

def run_interactive(args):
    end = False; i = 0
    while i < len(args):
        a = args[i]
        if not end and a == '--': end = True; i += 1; continue
        if not end and a in ('-h', '--help'):
            sys.stdout.write(INT_HELP); return 0
        if not end and a in ('-e', '--no-entry-check'):
            i += 1; continue
        if not end and a.startswith('-') and a != '-':
            return invalid_unexpected(a, 'executable interactive [OPTIONS] [INPUT]...')
        i += 1
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        sys.stderr.write('Error: Interactive mode requires a connected terminal\n')
        return 1
    # Minimal terminal UI fallback: clear screen and show help-like prompt.
    sys.stdout.write('\033[?1049h\033[2J\033[Hdua interactive - press q to quit')
    sys.stdout.flush()
    try:
        while True:
            ch = sys.stdin.read(1)
            if ch in ('q', '\x03', ''):
                break
    finally:
        sys.stdout.write('\033[?1049l')
        sys.stdout.flush()
    return 0

def run_completions(args):
    if args and args[0] in ('-h','--help'):
        sys.stdout.write(COMP_HELP); return 0
    if not args:
        return eprint_error('the following required arguments were not provided:\n  <SHELL>', usage='executable completions <SHELL>')
    shell = args[0]
    if shell not in ('bash','elvish','fish','powershell','zsh'):
        return eprint_error(f"invalid value '{shell}' for '<SHELL>'", extra="  [possible values: bash, elvish, fish, powershell, zsh]\n")
    base = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'src', 'completions', shell + '.txt')
    if not os.path.exists(base):
        # When run directly from src/dua.py
        base = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'completions', shell + '.txt')
    try:
        with open(base, 'rb') as f:
            sys.stdout.buffer.write(f.read())
    except OSError:
        pass
    return 0

def run_help(args):
    if not args:
        sys.stdout.write(LONG_HELP); return 0
    sub = args[0]
    if sub in ('aggregate','a'):
        sys.stdout.write(AGG_HELP); return 0
    if sub in ('interactive','i'):
        sys.stdout.write(INT_HELP); return 0
    if sub == 'completions':
        sys.stdout.write(COMP_HELP); return 0
    if sub == 'help':
        sys.stdout.write(LONG_HELP); return 0
    return eprint_error(f"unrecognized subcommand '{sub}'", usage='dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]...')

def main(argv):
    cfg, inputs, sub, rest, status = parse_global(argv)
    if status == 'exit0':
        return 0
    if isinstance(status, int) and status != 0:
        return status
    if sub in ('aggregate','a'):
        parsed = parse_aggregate_args(rest)
        if parsed is None:
            return 0
        if isinstance(parsed, int):
            return parsed
        inps, no_sort, no_total, stats = parsed
        return run_aggregate(cfg, inps, no_sort, no_total, stats)
    if sub in ('interactive','i'):
        return run_interactive(rest)
    if sub == 'completions':
        return run_completions(rest)
    if sub == 'help':
        return run_help(rest)
    return run_aggregate(cfg, inputs, False, False, False)

if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try:
            sys.stdout.close()
        finally:
            sys.exit(0)
PY
